from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

    def describe(self):
        return "Shape Description"

    def __str__(self):
        return f"{self.describe()}\n{self.__class__.__name__} Area: {self.area():.2f}"

class Triangle(Shape):
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self):
        return 0.5 * self.base * self.height

class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side * self.side

import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    t_line = lines[0].strip().split()
    s_line = lines[1].strip().split()

    base = float(t_line[0])
    height = float(t_line[1])
    side = float(s_line[0])

    triangle = Triangle(base, height)
    square = Square(side)

    shapes = [triangle, square]

    for shape in shapes:
        print(shape)

    del triangle
    del square

if __name__ == "__main__":
    main()
